def transform(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    cells={}
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg: cells.setdefault(g[r][c],[]).append((r,c))
    out=[row[:] for row in g]
    for col,pts in cells.items():
        if len(pts)<2: continue
        pts.sort()
        dr=pts[1][0]-pts[0][0]; dc=pts[1][1]-pts[0][1]
        s=(dr//abs(dr) if dr else 0, dc//abs(dc) if dc else 0)
        r,c=pts[0]
        while True:
            r-=s[0]; c-=s[1]
            if r<0 or c<0 or r>=h or c>=w: break
            out[r][c]=col
    return out

