prog = '''import json, os
from collections import Counter

def transform(grid):
    grid = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    comps = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                comps.setdefault(grid[r][c], set()).add((r, c))

    def diag_runs(s):
        """maximal runs (len>=2) along the two diagonal orientations"""
        runs = []
        for dr, dc in ((1, 1), (1, -1)):
            seen = set()
            for (r, c) in s:
                if (r - dr, c - dc) in s or (r, c) in seen:
                    continue
                run, rr, cc = [], r, c
                while (rr, cc) in s:
                    run.append((rr, cc)); seen.add((rr, cc)); rr += dr; cc += dc
                if len(run) >= 2:
                    runs.append(run)
        return runs

    def ext_end(s, r, c, dr, dc):
        """cells beyond (r,c) stepping (-dr,-dc)... extend opposite: from end (r,c) continue (dr,dc)"""
        res = []
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
            res.append((rr, cc)); rr += dr; cc += dc
        return res

    for col, s in comps.items():
        if len(s) < 2:
            continue
        if len(s) >= 3:
            for run in diag_runs(s):
                a, b = run[0], run[-1]
                dr = (b[0] > a[0]) - (b[0] < a[0]); dc = (b[1] > a[1]) - (b[1] < a[1])
                for (r, c, ddr, ddc) in ((a[0], a[1], -dr, -dc), (b[0], b[1], dr, dc)):
                    for rr, cc in ext_end(s, r, c, ddr, ddc):
                        grid[rr][cc] = col
        else:
            # 2-cell line: extends from the end opposite a diagonally touching
            # foreign-color cell (an "anchor tip"), if such an anchor exists
            (a, b) = tuple(s)
            for (end, other) in ((a, b), (b, a)):
                dr = (other[0] > end[0]) - (other[0] < end[0])
                dc = (other[1] > end[1]) - (other[1] < end[1])
                anchor = (end[0] - dr, end[1] - dc)  # cell beyond `end`, opposite side of the line
                if 0 <= anchor[0] < h and 0 <= anchor[1] < w and grid[anchor[0]][anchor[1]] not in (bg, col):
                    # anchor touches the `end` cell diagonally/orthogonally: extend from the OTHER cell
                    far = b if end == a else a
                    for rr, cc in ext_end(s, far[0], far[1], dr, dc):
                        grid[rr][cc] = col
                    break
    return grid

if __name__ == '__main__':
    d = os.path.dirname(os.path.abspath(__file__))
    for i, p in enumerate(json.load(open(os.path.join(d, 'task-51cdabe4.json')))):
        assert transform(p['input']) == p['output'], f'pair {i} mismatch'
    print('all', i + 1, 'pairs reproduce OK')
'''
